];
$socials=[];foreach($socialDefs as $key=>$def){$url=trim((string)($publicSettings['public_social_'.$key.'_url']??$def[3]));$enabled=(string)($publicSettings['public_social_'.$key.'_enabled']??($url!==''?'1':'0'))==='1';$order=(int)($publicSettings['public_social_'.$key.'_order']??(count($socials)+1));if($enabled&&$url!==''&&filter_var($url,FILTER_VALIDATE_URL))$socials[]=['key'=>$key,'label'=>$def[0],'icon'=>$def[1],'color'=>$def[2],'url'=>$url,'order'=>$order];}usort($socials,fn($a,$b)=>$a['order']<=>$b['order']);
$floatSocials=(string)($publicSettings['public_social_float_enabled']??'1')==='1';$footerSocials=(string)($publicSettings['public_social_footer_enabled']??'1')==='1';$floatSideRaw=(string)($publicSettings['public_social_float_side']??'right');$floatSide=in_array($floatSideRaw,['left','right'],true)?$floatSideRaw:'right';$floatVerticalRaw=(string)($publicSettings['public_social_float_vertical']??'center');$floatVertical=in_array($floatVerticalRaw,['top','center','bottom'],true)?$floatVerticalRaw:'center';
$turnstileEnabled=(string)($publicSettings['public_turnstile_enabled']??'0')==='1';$turnstileSiteKey=trim((string)($publicSettings['public_turnstile_site_key']??''));$turnstileActive=$turnstileEnabled&&$turnstileSiteKey!=='';
