  -H "Content-Type: application/json" \
  -H "Idempotency-Key: whatsapp-msg-987654" \
  -d '{
    "channel_id": 12,
    "from": "+50499999999",
    "contact_name": "Juan Pérez",
    "message": "Hola, necesito información"
  }'</code></pre><div class="docs-flow"><i class="fa-solid fa-diagram-project"></i><span>Sistema externo</span><i class="fa-solid fa-arrow-right"></i><span>ZYNKO</span><i class="fa-solid fa-arrow-right"></i><span>Canal</span><i class="fa-solid fa-arrow-right"></i><span>Conversación</span><i class="fa-solid fa-arrow-right"></i><span>NIVO IA</span><i class="fa-solid fa-arrow-right"></i><span>Respuesta / handoff</span></div><div class="docs-response"><div class="docs-response-head"><b>NIVO devuelve su decisión</b><button type="button" class="docs-copy-mini" data-copy-target="publicReceiveResponse"><i class="fa-regular fa-copy"></i> Copiar</button></div><pre id="publicReceiveResponse"><code>{
